%[text] ## 3 LMS参数自适应迭代
%[text] 在Landau等人的研究中，使用$\\phi \\;{\\left(t\\right)}^{\\top \\;} \\hat{\\theta \\;} \\left(t\\right)${"editStyle":"visual"}与经过滤波的估计干扰$w\_1 \\left(t\\right)${"editStyle":"visual"}合成了一个“误差信号”$\\varepsilon \\;\\left(t\\right)${"editStyle":"visual"}，并使用RLS算法进行参数自适应。
%[text] 此处的RLS算法能否使用LMS算法替代呢？可以试试。
Q = zeros(1,nQ+1);
%% 自适应参数初始化
stepSize = 1e-7; 
nB = length(B)-1;
nA = length(A);
nS = length(So);

Phi = zeros(1,nQ+1);
F = 10e3.*eye(nQ+1);

N = max([nA, nB, nS, length(Po)]);
U = zeros(1,N);
Y = zeros(1,N);
Yf = zeros(1,N);
W = zeros(1,N);
W1 = zeros(1,N);
W2 = zeros(1,N);

%% 自适应仿真循环
u = zeros(size(t)); % Control input
y = zeros(size(t)); % System output
antinoise = zeros(size(t));
w = zeros(size(t)); % Observer output
w1 = zeros(size(t));
w2 = zeros(size(t));
e0 = zeros(size(t)); % Adaptation error
e = zeros(size(t)); % Adaptation error

for k = 1:length(t)
    
    % Plant输出的测量
    antinoise(k) = FIR(B(2:end),U) - FIR(A(2:end),Yf);
    Yf = [antinoise(k), Yf(1:end-1)];
    y(k) = antinoise(k) + disturbance(k);
    Y = [y(k),Y(1:end-1)];

    % 扰动观测值
    w(k) = FIR(A, Y) - FIR(Bo_star, U);
    W = [w(k),W(1:end-1)];
    w1(k) = FIR(So, W) - FIR(Po(2:end), W1);
    W1 = [w1(k),W1(1:end-1)];
    % 先验/后验误差
    e0(k) = w1(k) - FIR(Q, Phi);
    % 自适应参数更新（LMS）
    Q = Q + stepSize.* Phi* e0(k);

    % 计算控制输入
    u(k) = -FIR(Ro, Y) - FIR(conv(conv(HR,HS),Q), W) - FIR(So(2:end), U);
    % 饱和 
    % u(k) = sat(u(k),5);
    U = [u(k), U(1:end-1)];
    
    % 为下一时刻做准备
    w2(k) =  FIR(conv(conv(HR,HS),Bo_star), W) - FIR(Po(2:end), W2);
    W2 = [w2(k), W2(1:end-1)];
    Phi = [w2(k), Phi(1:end-1)];
    % F_new = lambda1.* inv(F) + lambda2 .* (Phi' * Phi);
    % F_new = F_new + 1e-8*eye(size(F_new));
    % F = inv(F_new);
    % if any(isnan(F(:))) || any(isinf(F(:))) || rcond(F) < 1e-12
    %     error('F矩阵奇异或数值不稳定，脚本已终止。');
    % end
end

