%[text] ## 4 时变噪声信号仿真
%%
%[text] ### 4.1 时变信号生成
Ns = 10000;
t = linspace(0,Ns*Ts,Ns);
Amp = [1.0, 0.8];                           % 两个分量幅值
varfreq = 15;
f1_t = linspace(100-varfreq, 100+varfreq, length(t));     % 分量1：线性扫频 80 -> 120 Hz
f2_t = 200 + varfreq*sin(2*pi*0.1*t);           % 分量2：正弦调频，中心190Hz，幅度20Hz，调制速率1Hz
% 相位由瞬时频率积分得到
phi1 = 2*pi*cumtrapz(t, f1_t);
phi2 = 2*pi*cumtrapz(t, f2_t);
sig1 = Amp(1) * sin(phi1);
sig2 = Amp(2) * sin(phi2);
disturbance = sig1 + sig2;              
% 计算解析信号以得到包络与瞬时频率
analytic_sig = hilbert(disturbance);
inst_envelope = abs(analytic_sig);
inst_phase = unwrap(angle(analytic_sig));
inst_freq = [0, (Fs/(2*pi)) * diff(inst_phase)]; % Hz，长度与 t 一致

% 绘制时域与时频图供分析（可移到文件末尾）
figure('Name','扰动时域与时频图','NumberTitle','off'); %[output:03eeeeab]
plot(t, disturbance); %[output:03eeeeab]
xlabel('时间 (s)'); ylabel('幅值'); %[output:03eeeeab]
title('扰动 — 时域信号'); %[output:03eeeeab]
xlim([0 t(end)]); %[output:03eeeeab]
grid on; %[output:03eeeeab]
% 改进的 spectrogram：更短窗以提高时间分辨率，并在上面叠加瞬时频率
win = 512;                 % 较短窗，提升时间分辨率
overlap = round(0.75*win);
nfft = 2*1024;
figure('Name','扰动时频图（高时间分辨率）','NumberTitle','off'); %[output:2715c458]
spectrogram(disturbance, hamming(win), overlap, nfft, Fs, 'yaxis'); %[output:2715c458]
title('扰动 — Spectrogram (短窗，高时间分辨率)'); %[output:2715c458]
ylim([0 0.35]); % 单位为 kHz，这里显示 0 - 350 Hz %[output:2715c458]
colormap jet; colorbar; %[output:2715c458]
