%[text] ### 4.2 RLS自适应仿真
Q = zeros(1,nQ+1);
%% 自适应参数初始化
lambda1 = 0.98; % Forgetting factor
lambda2 = 1; % Adaptation gain
nB = length(B)-1;
nA = length(A);
nS = length(So);

Phi = zeros(1,nQ+1);
